def solve(grid):
    R = len(grid)
    C = len(grid[0])

    # Find background, base, and anomaly colors
    counts = {}
    for r in range(R):
        for c in range(C):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1

    sorted_colors = sorted(counts.keys(), key=lambda x: counts[x], reverse=True)
    bg_color = sorted_colors[0]
    base_color = sorted_colors[1]
    anomaly_color = None
    if len(sorted_colors) > 2:
        anomaly_color = sorted_colors[2]

    # Determine depth by finding N such that R = H^N and C = W^N
    # for small integers H, W, N
    best_H, best_W = 0, 0
    for N in range(2, 6):
        H = round(R ** (1.0 / N))
        W = round(C ** (1.0 / N))
        if H ** N == R and W ** N == C:
            best_H, best_W = H, W
            break

    if best_H == 0:
        best_H, best_W = R, C

    H, W = best_H, best_W

    # Construct the output tile
    output = [[bg_color for _ in range(W)] for _ in range(H)]

    # Fill base color
    for r in range(R):
        for c in range(C):
            if grid[r][c] == base_color:
                output[r % H][c % W] = base_color

    # Overlay anomaly color
    if anomaly_color is not None:
        for r in range(R):
            for c in range(C):
                if grid[r][c] == anomaly_color:
                    output[r % H][c % W] = anomaly_color

    return output
